import { isValidNumber } from '@zcatalyst/utils';
import { NoSQLByte } from './byte';
import { NoSQLByteSet, NoSQLNumberSet, NoSQLStringSet } from './set';
export class NoSQLUnMarshall {
    static makeNative(attr) {
        const [k, v] = Object.entries(attr)[0];
        if (v === undefined) {
            throw new Error(`No value defined: ${JSON.stringify(attr)}`);
        }
        switch (k) {
            case 'NULL': {
                return null;
            }
            case 'BOOL':
                return v === 'true';
            case 'N':
                return this.makeNumber(v);
            case 'B':
                return typeof v === 'string' ? new NoSQLByte(v) : v;
            case 'S':
                return v;
            case 'L':
                return NoSQLUnMarshall.makeList(v);
            case 'M':
                return NoSQLUnMarshall.makeMap(v);
            case 'SN':
                return v instanceof NoSQLNumberSet
                    ? v
                    : new NoSQLNumberSet(v.map((item) => this.makeNumber(item)));
            case 'SB':
                return v instanceof NoSQLByteSet ? v : new NoSQLByteSet(v);
            case 'SS':
                return v instanceof NoSQLStringSet ? v : new NoSQLStringSet(v);
            default:
                throw new Error(`Unsupported type passed: ${k}`);
        }
    }
    static makeList(list) {
        return list.map((item) => NoSQLUnMarshall.makeNative(item));
    }
    static makeMap(map) {
        return Object.entries(map).reduce((acc, [key, value]) => {
            acc[key] = this.makeNative(value);
            return acc;
        }, {});
    }
    static makeNumber(numStr) {
        const num = Number(numStr);
        if (isValidNumber(num, false)) {
            return num;
        }
        return BigInt(numStr);
    }
}
